#include "mlir/Dialect/Func/IR/FuncOps.h"
#include "mlir/Dialect/Linalg/IR/Linalg.h"
#include "mlir/Dialect/Tensor/IR/Tensor.h"
#include "mlir/IR/Builders.h"
#include "mlir/IR/BuiltinAttributes.h"
#include "mlir/IR/Location.h"
#include "mlir/IR/OperationSupport.h"
#include "mlir/IR/PatternMatch.h"
#include "mlir/Pass/Pass.h"
#include "mlir/Transforms/DialectConversion.h"
#include "mlir/Transforms/GreedyPatternRewriteDriver.h"

#define GEN_PASS_DECL_REMOVESCALAR
#define GEN_PASS_DEF_REMOVESCALAR
#include "evas/Transform/Linalg/Passes.h.inc"

#define DEBUG_TYPE "convert-to-2d"

/*
  description: Eliminate the scalars generated by the reduce operation in the
  scalar-matrix multiplication process

  example :
    before :
      %extracted_11 = tensor.extract %reduced_9[%c0_10] : tensor<1xf32>
      %16 = tensor.empty() : tensor<3x2xf32>
      %17 = linalg.fill ins(%extracted_11 : f32) outs(%16 : tensor<3x2xf32>) ->
    tensor<3x2xf32>

    after:
      %7 = tensor.empty() : tensor<3x2x1xf32>
      %broadcasted = linalg.broadcast ins(%reduced : tensor<1xf32>) outs(%7 :
  tensor<3x2x1xf32>) dimensions = [0, 1] %collapsed_0 = tensor.collapse_shape
  %broadcasted [[0], [1, 2]] : tensor<3x2x1xf32> into tensor<3x2xf32>

  special case :
    before :
      %extracted = tensor.extract %reduced[%c0] : tensor<1xf32>
      %6 = tensor.empty() : tensor<1xf32>
      %7 = linalg.fill ins(%extracted : f32) outs(%6 : tensor<1xf32>) ->
  tensor<1xf32>

    after: (Completely eliminated)

*/

namespace mlir::triton::ev {

namespace {
using namespace mlir;

struct RemoveScalarPattern : public OpRewritePattern<tensor::ExtractOp> {
  using OpRewritePattern<tensor::ExtractOp>::OpRewritePattern;

  LogicalResult matchAndRewrite(tensor::ExtractOp op,
                                PatternRewriter &rewriter) const override {
    Location loc = op.getLoc();
    Value extractResult = op.getResult();
    if (!extractResult.hasOneUse()) {
      return failure();
    }

    Operation *nextOp = *extractResult.getUsers().begin();
    auto fillOp = dyn_cast<linalg::FillOp>(nextOp);
    if (!fillOp) {
      return failure();
    }

    Value sourceTensor = op.getTensor();
    auto destType = cast<RankedTensorType>(fillOp.getOutputs()[0].getType());

    std::vector<long> emptyShape = destType.getShape().vec();
    emptyShape.push_back(1);

    bool isEmptyShapeAllOnes = true;
    for (int64_t dim : emptyShape) {
      if (dim != 1) {
        isEmptyShapeAllOnes = false;
        break;
      }
    }

    if (isEmptyShapeAllOnes) {
      SmallVector<ReassociationIndices> reassociation;
      ReassociationIndices expandIndices;
      for (int i = 0; i < destType.getRank(); i++) {
        expandIndices.push_back(i);
      }
      reassociation.push_back(expandIndices);

      auto expanded = rewriter.create<tensor::ExpandShapeOp>(
          loc, destType, sourceTensor, reassociation);

      rewriter.replaceOp(fillOp, expanded.getResult());
      rewriter.eraseOp(op);
    } else {
      Value empty = rewriter.create<tensor::EmptyOp>(loc, emptyShape,
                                                     destType.getElementType());

      SmallVector<int64_t> broadcastDims;
      for (int64_t i = 0; i < destType.getRank(); i++) {
        broadcastDims.push_back(i);
      }

      auto broadcastOp = rewriter.create<linalg::BroadcastOp>(
          loc, sourceTensor, empty, broadcastDims);

      SmallVector<ReassociationIndices> reassociation;
      for (int i = 0; i < destType.getRank(); i++) {
        reassociation.push_back({i});
      }
      reassociation.back().push_back(destType.getRank());

      auto collapsedOp = rewriter.create<tensor::CollapseShapeOp>(
          loc, fillOp.getOutputs()[0].getType(), broadcastOp.getResult()[0],
          reassociation);

      rewriter.replaceOp(fillOp, collapsedOp.getResult());
      rewriter.eraseOp(op);
      if (Operation *emptyOp = fillOp.getOutputs()[0].getDefiningOp()) {
        rewriter.eraseOp(emptyOp);
      }
    }

    return success();
  }

private:
};

struct RemoveScalarPass : public ::impl::RemoveScalarBase<RemoveScalarPass> {
  using RemoveScalarBase<RemoveScalarPass>::RemoveScalarBase;

public:
  void getDependentDialects(DialectRegistry &registry) const override {
    registry.insert<func::FuncDialect, linalg::LinalgDialect, tensor::TensorDialect>();
  }
  void runOnOperation() override {
    mlir::ModuleOp moduleOp = getOperation();
    MLIRContext &context = getContext();
    
    RewritePatternSet patterns(&context);
    patterns.add<RemoveScalarPattern>(&context);

    if (failed(applyPatternsGreedily(moduleOp, std::move(patterns)))) {
      signalPassFailure();
    }
  }
};
} // namespace
std::unique_ptr<mlir::Pass> createRemoveScalarPass() {
  return std::make_unique<RemoveScalarPass>();
}
} // namespace mlir::triton::ev